<script setup>
import { ArrowDownBold, View, Hide } from '@element-plus/icons-vue'
defineProps({ assetsVisible:Boolean, assetsCollapsed:Boolean, realtimeAvailable:Number, portfolioMarketValue:Number, portfolioFloatingPnl:Number, floatingPnlClass:String, assetAmountParts:Function })
const emit = defineEmits(['toggle-visibility','update:collapsed'])
const money = value => Number(value).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})
const signedMoney = value => `${Number(value)>0?'+':''}${money(value)}`
function toggleAssetsVisible() { emit('toggle-visibility') }
</script>
<template>
<section class="compact-assets ticket-assets is-portfolio-summary" :class="{ 'is-collapsed': assetsCollapsed }" aria-label="账户资金"><div class="asset-summary-heading"><span>资产账户概要</span><button class="asset-visibility" type="button" :aria-label="assetsVisible ? '隐藏资金数值' : '查看资金数值'" @click="toggleAssetsVisible"><el-icon><View v-if="assetsVisible" /><Hide v-else /></el-icon></button><button class="asset-collapse" type="button" :aria-label="assetsCollapsed ? '展开资产账户概要' : '收起资产账户概要'" @click="emit('update:collapsed', !assetsCollapsed)"><el-icon><ArrowDownBold /></el-icon></button></div><div v-show="!assetsCollapsed" class="asset-summary-grid"><div class="asset-metric asset-available"><span>大账户实时可用</span><el-tooltip v-if="assetsVisible" placement="top" popper-class="asset-value-popper"><template #content><span class="asset-large-value"><template v-for="part in assetAmountParts(realtimeAvailable)" :key="`${part.value}${part.unit}`"><b>{{ part.value }}</b><i v-if="part.unit">{{ part.unit }}</i></template></span></template><b class="asset-number">{{ money(realtimeAvailable) }}</b></el-tooltip><b v-else class="asset-number">••••••••</b><small>CNY</small></div><div class="asset-metric"><span>持仓市值</span><el-tooltip v-if="assetsVisible" placement="top" popper-class="asset-value-popper"><template #content><span class="asset-large-value"><template v-for="part in assetAmountParts(portfolioMarketValue)" :key="`${part.value}${part.unit}`"><b>{{ part.value }}</b><i v-if="part.unit">{{ part.unit }}</i></template></span></template><b class="asset-number">{{ money(portfolioMarketValue) }}</b></el-tooltip><b v-else class="asset-number">••••••••</b><small>CNY</small></div><div class="asset-metric"><span>浮动盈亏</span><el-tooltip v-if="assetsVisible" placement="top" popper-class="asset-value-popper"><template #content><span class="asset-large-value"><template v-for="part in assetAmountParts(portfolioFloatingPnl, true)" :key="`${part.value}${part.unit}`"><b>{{ part.value }}</b><i v-if="part.unit">{{ part.unit }}</i></template></span></template><b class="asset-number" :class="floatingPnlClass">{{ signedMoney(portfolioFloatingPnl) }}</b></el-tooltip><b v-else class="asset-number">••••••••</b><small>CNY</small></div></div></section>
</template>
